g.add(mesh(boxG,wallDarkM,0,6.0,zf(6.3)+0.05,5.2,0.7,1.6,0));
g.add(mesh(boxG,gateTopM,0,6.7,zf(7.0)-0.1,3.6,0.55,1.3,0));
