let ntr=0,nti=0,nbl=0,nfr=0,ngl=0;
const GREENS=[0x2e7d3a,0x3c9a4a,0x1f5c2a,0x5cb85c,0x2a6f5a,0x7fc95a,0x3f8f5f,0x1c4a30,0x4fb37a,0x2f8a6e];
