      if(k===6&&u<0.45&&!popped[i]){popped[i]=1;life[i]=0;for(let j=0;j<3;j++)spawn(fp[e],fp[e+1],fp[e+2],(R()-0.5)*9,(R()-0.5)*9,(R()-0.5)*9,[1,1,0.95],0.22+R()*0.1,7);}
