  {const ex=(x-ARENA.x)/60,ez=(z-ARENA.z)/52;if(ex*ex+ez*ez<1)return {title:'The Arena',lines:[{t:'Evening sessions under floodlights from about 17:00.'},{t:'Fighters on the sand, crowds on the tiers.',sub:true}]};}
